    "id": "pin-nazca",
    "title_th": "ลายเส้นปริศนานัซกา ธรณีศิลป์แห่งแอนดีส",
    "title_en": "The Nazca Lines Geoglyphs",
    "category": "sacred",
    "province_th": "นัซกา (เปรู)",
