    "id": "pin-lallorona",
    "title_th": "ลาโยโรนา หญิงคร่ำครวญแห่งสายน้ำ",
    "title_en": "La Llorona, The Weeping Woman",
    "category": "ghost",
    "province_th": "เม็กซิโกซิตี (เม็กซิโก)",
